#[test]
fn the_case_table_must_match_the_case_directories_exactly() {
    let swapped = "#[path = \"benchmarks/1_a/case.rs\"]\nmod n2_b;\n#[path = \"benchmarks/2_b/case.rs\"]\nmod n1_a;\n\nconst CASES: &[(&str, Measure)] = &[\n    (\"1_a\", n1_a::measure),\n    (\"2_b\", n2_b::measure),\n];\n";
    let root = tree(
        "layout-table",
        &[
            ("benchmarks/1_a/case.toml", PLANNED),
            ("benchmarks/2_b/case.toml", PLANNED),
            ("tests/benchmarks/1_a/case.rs", ""),
            ("tests/benchmarks/2_b/case.rs", ""),
            ("tests/benchmarks.rs", &runner(swapped)),
        ],
    );
    assert!(has(
        &lever(&["layout"], &root),
        "the case table in tests/benchmarks.rs differs"
    ));
    write(&root, "tests/benchmarks.rs", "fn main() {}\n");
    assert!(has(
        &lever(&["layout"], &root),
        "lacks the line `// cases: begin"
    ));
}

#[test]
fn new_case_takes_the_next_number_and_regenerates_the_table() {
    let root = tree(
        "layout-new",
        &[
            ("benchmarks/1_a/case.toml", PLANNED),
            ("tests/benchmarks/1_a/case.rs", ""),
            ("tests/benchmarks.rs", &runner("")),
        ],
    );
    assert!(has(&lever(&["new-case", "eos", "magic"], &root), "usage"));
    for slug in ["", "Eos", "si-eos"] {
        assert!(
            has(&lever(&["new-case", slug, "analytic"], &root), "usage"),
            "{slug:?}"
        );
    }
    assert!(lever(&["new-case", "si_eos", "all-electron"], &root).is_empty());
    let case = std::fs::read_to_string(root.join("benchmarks/2_si_eos/case.toml")).unwrap();
    assert!(case.contains("reference = \"all-electron\"") && case.contains("planned"));
    let what = std::fs::read_to_string(root.join("benchmarks/results-what.toml")).unwrap();
    assert_eq!(what, "\n[2]\nwhat = \"si eos\"\nmetric = []\nunit = \"\"\n");
    assert!(
        lever(&["layout"], &root).is_empty(),
        "{:?}",
        lever(&["layout"], &root)
    );
    write(&root, "tests/benchmarks.rs", "fn main() {}\n");
    assert!(has(
        &lever(&["new-case", "x", "analytic"], &root),
        "lacks the line"
    ));
    assert!(!root.join("benchmarks/3_x").exists());
}

#[test]
fn a_two_digit_case_keeps_the_table_as_rustfmt_orders_it() {
    let root = tree(
        "layout-two-digits",
        &[
            ("benchmarks/DATASETS.toml", ""),
            ("tests/benchmarks.rs", &runner("")),
        ],
    );
    for slug in ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"] {
        assert!(lever(&["new-case", slug, "analytic"], &root).is_empty());
    }
    let check = std::process::Command::new("rustfmt")
        .args(["--edition", "2024", "--check", "tests/benchmarks.rs"])
        .current_dir(&root)
        .output()
        .unwrap();
    assert!(
        check.status.success(),
        "{}",
        String::from_utf8_lossy(&check.stdout)
    );
    assert!(lever(&["layout"], &root).is_empty());
}

